"""Return both arms to their reset poses and re-measure the whole arrangement."""
import json
import numpy as np
from robot import tools, handoff
from ora_lib import current, object_geometry
import policy_lib as P

r = tools.return_home(arms=["left", "right"])
print("return_home:", r.status, (r.summary or "")[:140])

cur = current()
reset_ref = {"left": np.array([-0.2995290756225586, -0.35229986906051636, 0.921500027179718]),
             "right": np.array([0.3004709482192993, -0.35229986906051636, 0.921500027179718])}
for arm in ["left", "right"]:
    pos = np.asarray(cur.pose(arm).xyz.tolist(), float)
    print(arm, "tcp", np.round(pos, 4).tolist(), "reset distance", round(float(np.linalg.norm(pos-reset_ref[arm])), 5))

baskets = P.basket_geometry()
info = {}
for k, g in baskets.items():
    amin = np.asarray(g.aabb_min_xyz_m, float); amax = np.asarray(g.aabb_max_xyz_m, float)
    info[k] = (amin, amax, float(amax[2]))

classes = {"plush toy": "white", "action camera": "blue", "camera": "blue", "go pro": "blue", "pen": "red"}
seen = {}
for text, basket in classes.items():
    amin, amax, rim = info[basket]
    rr = tools.vision_ground(camera="head", text=text, max_candidates=3)
    for c in rr["result"].get("candidates", []) or []:
        try: g = object_geometry(c)
        except Exception: continue
        ctr = np.asarray(g.center_xyz_m, float)
        if not (amin[0]-0.02 <= ctr[0] <= amax[0]+0.02 and amin[1]-0.02 <= ctr[1] <= amax[1]+0.02):
            continue
        if ctr[2] >= rim:
            print(f"{text}: ABOVE rim {np.round(ctr,3).tolist()}")
            continue
        key = (basket, tuple(np.round(ctr, 2)))
        if key in seen: continue
        seen[key] = (text, ctr, np.asarray(g.principal_extents_m, float), float(np.asarray(g.aabb_max_xyz_m, float)[2]))
for (basket, _), (text, ctr, ext, zmax) in sorted(seen.items()):
    print(f"IN {basket:5s} '{text}' centre {np.round(ctr,4).tolist()} ext {np.round(ext,3).tolist()} zmax {zmax:.3f} rim {info[basket][2]:.3f}")
print("counts:", {b: sum(1 for (bb, _) in seen if bb == b) for b in info})
